-- Curate Hungary into compact chronological browsing.
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TEMP TABLE hu_tree(concept_id TEXT PRIMARY KEY) WITHOUT ROWID;
WITH RECURSIVE t(id) AS (VALUES('unified:f3ca3e31-4ea8-5bfb-aaa5-0e92c65ac0de') UNION SELECT p.concept_id FROM t JOIN concept_parent p ON p.parent_concept_id=t.id) INSERT INTO hu_tree SELECT id FROM t;

