CREATE TEMP TABLE hu_keep(concept_id TEXT PRIMARY KEY) WITHOUT ROWID;
INSERT INTO hu_keep SELECT concept_id FROM concept WHERE concept_id='unified:f3ca3e31-4ea8-5bfb-aaa5-0e92c65ac0de' OR concept_id LIKE 'bokheim:hungary:%' OR concept_id IN
('bokheim:history-lcc-full:201ffeda-f3e4-5aa4-bd01-d3e5d411d002','bokheim:history-lcc:97589f6f-9213-5436-8857-2fe7643c1964','bokheim:history-lcc:a513a9b3-baa2-5cd4-9abf-e1bcad2f3b4a','bokheim:history-lcc:0777e606-e7c8-5502-a0ee-33b8f2f64cb6','bokheim:history-lcc-full:0661741f-f84c-5497-ae85-60f406da1ef3','bokheim:history-lcc-full:39145c6a-60ed-5dcb-8983-26c30694daa4','bokheim:history-lcc:bb8d4e78-3651-572a-86a7-cc6c2f506b33','bokheim:history-lcc-full:a92db9a3-f8a9-518f-8f11-c224711678b6','bokheim:history-lcc-full:d68e823d-dd50-555f-9f74-09241127ce5f','bokheim:history-lcc:6f7a718b-c6ed-5e0f-a01a-152bb13c2b95','bokheim:history-lcc-full:dd111ddb-3b0c-5d0c-919e-c9c482500a37','bokheim:history-lcc-full:fa92ba9a-2351-5500-bffd-6c26334b4406','bokheim:history-lcc-full:3df248ba-a5c5-5588-bb15-1ad4db22fd35','bokheim:history-lcc-full:d350a2c7-389f-552d-acd0-316061bed71e','bokheim:history-lcc-full:7cde2cbd-082c-5406-8f53-ab50d28c84ab','bokheim:history-lcc:5c95adc1-ab14-5554-b185-aaa25e65cc3b','bokheim:history-lcc-full:2ed6bff3-fed4-58e1-8755-5c338063269b','bokheim:history-lcc:ce089122-242b-5780-85bf-e35906638267');

CREATE TEMP TABLE hu_shared(concept_id TEXT PRIMARY KEY) WITHOUT ROWID;
WITH RECURSIVE s(id) AS (SELECT t.concept_id FROM hu_tree t JOIN concept_parent p ON p.concept_id=t.concept_id WHERE p.parent_concept_id NOT IN (SELECT concept_id FROM hu_tree) AND t.concept_id<>'unified:f3ca3e31-4ea8-5bfb-aaa5-0e92c65ac0de' UNION SELECT p.concept_id FROM s JOIN concept_parent p ON p.parent_concept_id=s.id WHERE p.concept_id IN (SELECT concept_id FROM hu_tree)) INSERT INTO hu_shared SELECT id FROM s;
DELETE FROM concept_parent WHERE parent_concept_id IN (SELECT concept_id FROM hu_tree);
DELETE FROM concept_parent WHERE concept_id IN (SELECT concept_id FROM hu_tree WHERE concept_id NOT IN (SELECT concept_id FROM hu_keep) AND concept_id NOT IN (SELECT concept_id FROM hu_shared));
DELETE FROM concept WHERE concept_id IN (SELECT concept_id FROM hu_tree WHERE concept_id NOT IN (SELECT concept_id FROM hu_keep) AND concept_id NOT IN (SELECT concept_id FROM hu_shared));

CREATE TEMP TABLE hu_edge(child TEXT,parent TEXT,ord INTEGER,PRIMARY KEY(child,parent)) WITHOUT ROWID;
