INSERT INTO concept_parent(concept_id,parent_concept_id,ordinal,display_order) SELECT child,parent,COALESCE((SELECT max(ordinal)+1 FROM concept_parent WHERE concept_id=child),0),ord FROM hu_edge;

UPDATE concept SET preferred_label=CASE concept_id WHEN 'bokheim:history-lcc-full:201ffeda-f3e4-5aa4-bd01-d3e5d411d002' THEN 'Roman Pannonia' WHEN 'bokheim:history-lcc:97589f6f-9213-5436-8857-2fe7643c1964' THEN 'Árpád Dynasty, 896–1301' WHEN 'bokheim:history-lcc:a513a9b3-baa2-5cd4-9abf-e1bcad2f3b4a' THEN 'Elective Kings, 1301–1526' WHEN 'bokheim:history-lcc:0777e606-e7c8-5502-a0ee-33b8f2f64cb6' THEN 'Ottoman & Habsburg Hungary, 1526–1711' WHEN 'bokheim:history-lcc-full:0661741f-f84c-5497-ae85-60f406da1ef3' THEN 'Early Ottoman Period, 1526–1606' WHEN 'bokheim:history-lcc-full:39145c6a-60ed-5dcb-8983-26c30694daa4' THEN 'Late Ottoman Period, 1606–1699' WHEN 'bokheim:history-lcc:bb8d4e78-3651-572a-86a7-cc6c2f506b33' THEN 'Age of Absolutism, 1711–1792' WHEN 'bokheim:history-lcc-full:a92db9a3-f8a9-518f-8f11-c224711678b6' THEN 'Early National Period, 1792–1825' WHEN 'bokheim:history-lcc-full:d68e823d-dd50-555f-9f74-09241127ce5f' THEN 'Reform Era, 1825–1848' WHEN 'bokheim:history-lcc:6f7a718b-c6ed-5e0f-a01a-152bb13c2b95' THEN 'Revolution, 1848–1849' WHEN 'bokheim:history-lcc-full:dd111ddb-3b0c-5d0c-919e-c9c482500a37' THEN 'Neo-Absolutism, 1849–1867' WHEN 'bokheim:history-lcc-full:fa92ba9a-2351-5500-bffd-6c26334b4406' THEN 'Austria-Hungary, 1867–1918' WHEN 'bokheim:history-lcc-full:3df248ba-a5c5-5588-bb15-1ad4db22fd35' THEN 'World War I, 1914–1918' WHEN 'bokheim:history-lcc-full:d350a2c7-389f-552d-acd0-316061bed71e' THEN 'Revolutions, 1918–1920' WHEN 'bokheim:history-lcc-full:7cde2cbd-082c-5406-8f53-ab50d28c84ab' THEN 'World War II, 1939–1945' WHEN 'bokheim:history-lcc:5c95adc1-ab14-5554-b185-aaa25e65cc3b' THEN 'People’s Republic, 1949–1989' WHEN 'bokheim:history-lcc-full:2ed6bff3-fed4-58e1-8755-5c338063269b' THEN 'Hungarian Revolution, 1956' WHEN 'bokheim:history-lcc:ce089122-242b-5780-85bf-e35906638267' THEN 'Republic of Hungary, 1989–Present' ELSE preferred_label END WHERE concept_id IN (SELECT concept_id FROM hu_keep);
DROP TABLE hu_edge; DROP TABLE hu_shared; DROP TABLE hu_keep; DROP TABLE hu_tree;
COMMIT;
